using NeuroAccess.Nfc.TravelDocuments;
using NeuroAccess.Nfc.TravelDocuments.DataObjects;
using Waher.Networking;

namespace NeuroAccess.Nfc.Test
{
	[TestClass]
	public class EfSodTests
	{
		[TestMethod]
		[DataRow(null, "")]
		[DataRow(null, "")]
		[DataRow(null, "")]
		[DataRow(null, "")]
		[DataRow(null, "")]
		[DataRow(null, "")]
		[DataRow(null, "")]
		[DataRow("YBdfAQQwMTA3XzYGMDQwMDAwXAVhdWNubw==", "")]
		[DataRow("YBdfAQQwMTA3XzYGMDQwMDAwXAVhdWNnbg==", "")]
		[DataRow("YBhfAQQwMTA3XzYGMDQwMDAwXAZhdWNrbG4=", "")]
		[DataRow("YBZfAQQwMTA3XzYGMDQwMDAwXARhdWNu", "")]
		[DataRow("YBhfAQQwMTA3XzYGMDQwMDAwXAZhdWNnbm8=", "")]
		[DataRow("YBlfAQQwMTA3XzYGMDQwMDAwXAdhdWNrbG1u", "")]
		public void Test_01_Parse(string? EfCom, string EfSodBase64)
		{
			TravelDocumentsClient Client = new(new MockIsoDepInterface(), new DocumentInformation(), null)
			{
				PermitPlatformDependentValidation = false
			};
			byte[] Bin;

			if (EfCom is null)
				Client.AppInfo = new ApplicationLevelInformation([], 1, 8, 0, 0, null);
			else
			{
				Bin = Convert.FromBase64String(EfCom);
				Assert.IsTrue(TravelDocumentsClient.TryParseDataObject(Bin, Client,
					out ApplicationLevelInformation? AppInfo));
				Assert.IsNotNull(AppInfo);

				Client.AppInfo = AppInfo;
			}

			Bin = Convert.FromBase64String(EfSodBase64);
			Assert.IsTrue(TravelDocumentsClient.TryParseDataObject(Bin, Client, out DocumentSecurityObject? SecurityInfo));
		}

		internal class MockIsoDepInterface : IIsoDepInterface
		{
			public INfcTag? Tag => null;
			public void CloseIfOpen() { }
			public void Dispose() { }
			public Task<byte[]> ExecuteCommand(byte[] Command, ICommunicationLayer CommunicationLayer)
			{
				return Task.FromResult(Array.Empty<byte>());
			}

			public Task<byte[]> GetHighLayerResponse()
			{
				return Task.FromResult(Array.Empty<byte>());
			}

			public Task<byte[]> GetHistoricalBytes()
			{
				return Task.FromResult(Array.Empty<byte>());
			}

			public Task OpenIfClosed() => Task.CompletedTask;
			public void SetTimeout(int Timeout) { }
		}
	}
}
